struct submodule_ops {
    int (*init)(void);
    void (*uninit)(void);
};

static struct submodule_ops g_sub_table[] = {
#ifdef CFG_FEATURE_TRS_CORE
    {trs_core_init_module, trs_core_exit_module},
#endif
#ifdef CFG_FEATURE_TRS_STARS
    {init_trs_stars, exit_trs_stars},
