10	
11	#include <unistd.h>
12	#include <stdint.h>
13	
14	#include "securec.h"
15	
16	#include "ascend_hal.h"
17	#include "esched_user_interface.h"
18	
19	#include "trs_user_pub_def.h"
20	#include "trs_cb_event.h"
21	
22	#define CALLBACK_EVENT_THREAD_MAX 1024 /* halTsdrvCtl() determine max thread num */
23	
24	static void trs_cb_event_wait_init(uint32_t dev_id, uint32_t tid)
25	{
26	    struct event_info event;
27	
28	    /*
29	     * Tell the current grp that some tid is waiting for cb_event.
30	     * Prevents events that need to be dispatched from being discarded before calling trs_cb_event_wait
31	     */
32	    (void)halEschedWaitEvent(dev_id, TRS_CB_EVENT_GRP_ID, tid, 0, &event); /* timeout 0, means no wait */
33	}
34	
35	int trs_cb_event_init(uint32_t dev_id)
36	{
37	    struct esched_grp_para grp_para;
38	    unsigned long event_bitmap = (0x1 << EVENT_TS_CALLBACK_MSG);
39	    unsigned int tid;
40	    int ret;
41	
42	    /* process attach device only need once */
43	    ret = halEschedAttachDevice(dev_id);
44	    if (ret != DRV_ERROR_NONE) {
45	        if (ret != DRV_ERROR_PROCESS_REPEAT_ADD) {
46	            trs_err("Call halEschedAttachDevice failed. (dev_id=%u, ret=%d)\n", dev_id, ret);
47	            return ret;
48	        }
49	    }
50	
51	    /* process attach device only need once */
52	    grp_para.type = GRP_TYPE_BIND_CP_CPU;
53	    grp_para.threadNum = CALLBACK_EVENT_THREAD_MAX;
54	    grp_para.rsv[0] = 0; // rsv word 0
55	    grp_para.rsv[1] = 0; // rsv word 1
56	    grp_para.rsv[2] = 0; // rsv word 2
57	
58	    ret = esched_create_extend_grp(dev_id, TRS_CB_EVENT_GRP_ID, &grp_para);
59	    if (ret != DRV_ERROR_NONE) {
60	        if (ret != DRV_ERROR_GROUP_EXIST) {
61	            (void)halEschedDettachDevice(dev_id);
62	            trs_err("Call halEschedCreateGrp failed. (dev_id=%u, ret=%d)\n", dev_id, ret);
63	            return ret;
64	        }
65	    }
66	
67	    /* all the threads subscribe the callback event */
68	    for (tid = 0; tid < CALLBACK_EVENT_THREAD_MAX; tid++) {
69	        ret = halEschedSubscribeEvent(dev_id, TRS_CB_EVENT_GRP_ID, tid, event_bitmap);
70	        if (ret != DRV_ERROR_NONE) {
71	            (void)halEschedDettachDevice(dev_id);
72	            trs_err("Call halEschedSubscribeEvent failed. (dev_id=%u, tid=%u; ret=%d)\n", dev_id, tid, ret);
73	            return ret;
74	        }
75	        trs_cb_event_wait_init(dev_id, tid);
76	    }
77	    return DRV_ERROR_NONE;
78	}
79	
80	void trs_cb_event_uninit(uint32_t dev_id)
81	{
82	    (void)halEschedDettachDevice(dev_id);
83	}
84	
85	static void trs_cb_event_to_cqe(struct trs_cb_stars_event *event, struct trs_cb_cqe *cqe)
86	{
87	    cqe->cq_id = (unsigned short)(event->cqid & 0xfff);
88	    cqe->stream_id = event->stream_id;
89	    cqe->event_id = event->event_id;
90	    cqe->task_id = event->task_id;
91	    cqe->is_block = (unsigned char)event->is_block;
92	    cqe->host_func_cb_ptr = (((uint64_t)event->host_func_low) | ((uint64_t)event->host_func_high << 32)); /* bit 32 */
93	    cqe->fn_data_ptr = (((uint64_t)event->fn_data_low) | ((uint64_t)event->fn_data_high << 32));          /* bit 32 */
94	}
95	
96	int trs_cb_event_wait(uint32_t dev_id, uint32_t tid, int32_t timeout, uint8_t *buff)
97	{
98	    struct trs_cb_cqe *cqe = (struct trs_cb_cqe *)buff;
99	    struct event_info event;
100	    int ret;
101	
102	    if (cqe == NULL) {
103	        trs_err("Null ptr. (dev_id=%u, tid =%d)\n", dev_id, tid);
104	        return DRV_ERROR_PARA_ERROR;
105	    }
106	
107	    ret = halEschedWaitEvent(dev_id, TRS_CB_EVENT_GRP_ID, tid, timeout, &event);
108	    if (ret != DRV_ERROR_NONE) {
109	#ifndef EMU_ST
110	        trs_warn("Call halEschedWaitEvent warn. (dev_id=%u, tid =%d; ret=%d)\n", dev_id, tid, ret);
111	#endif
112	        return ret;
113	    }
114	
115	    if (event.comm.subevent_id == TRS_CB_HW_TIMEOUT_SUBEVENTID) {
116	        return DRV_ERROR_WAIT_TIMEOUT; /* cb Id is freed. Use this subevent to wakeup thread. */
117	    } else if (event.comm.subevent_id == TRS_CB_SW_SUBEVENTID) {
118	        if (event.priv.msg_len == sizeof(*cqe)) {
119	            (void)memcpy_s((void *)cqe, sizeof(*cqe), event.priv.msg, sizeof(*cqe));
120	            return DRV_ERROR_NONE;
121	        }
122	    } else {
123	        if (event.priv.msg_len == sizeof(struct trs_cb_stars_event)) {
124	            trs_cb_event_to_cqe((struct trs_cb_stars_event *)(event.priv.msg), cqe);
125	            return DRV_ERROR_NONE;
126	        }
127	    }
128	
129	    trs_err("Event Msg len is error. (dev_id=%u, tid=%d; msg_len=%u)\n", dev_id, tid, event.priv.msg_len);
130	    return DRV_ERROR_PARA_ERROR;
131	}
132	
133	/* process submit event, the device id is the destination devid */
134	int trs_cb_event_submit(uint32_t dev_id, char *sqe, uint32_t e_size)
135	{
136	    struct event_summary event;
137	    drvError_t ret;
138	
139	    event.pid = getpid();
140	    event.grp_id = TRS_CB_EVENT_GRP_ID;
141	    event.event_id = EVENT_TS_CALLBACK_MSG;
142	    event.subevent_id = TRS_CB_HW_SUBEVENTID;
143	    event.dst_engine = TS_CPU;
144	    event.policy = ONLY;
145	    event.msg_len = e_size;
146	    event.msg = sqe;
147	
148	    ret = halEschedSubmitEvent(dev_id, &event);
149	    if (ret != DRV_ERROR_NONE) {
150	        trs_err("Call halEschedSubmitEvent failed. (dev_id=%u, ret=%d)\n", dev_id, ret);
151	        return ret;
152	    }
153	
154	    return DRV_ERROR_NONE;
155	}
156

