402	{
403	    int ret = 0;
404	
405	    if ((info->prop == DRV_SQCQ_PROP_SQCQ_RESET) || (info->prop == DRV_SQCQ_PROP_SQ_PAUSE) ||
406	        (info->prop == DRV_SQCQ_PROP_SQ_RESUME)) {
