189	void trs_sq_munmap(struct trs_sq_map *sq_map)
190	{
191	    int i;
192	
193	    sq_map->que.addr = NULL;
194	    for (i = 0; i < TRS_UIO_ADDR_MAX; i++) {
195	        sq_map->ctrl[i].addr = NULL;
196	    }
197	
198	    if ((sq_map->non_reg_addr.addr != NULL) && (sq_map->non_reg_addr.addr != MAP_FAILED)) {
199	        (void)trs_dev_munmap(sq_map->non_reg_addr.addr, sq_map->non_reg_addr.len);
200	        sq_map->non_reg_addr.addr = NULL;
201	    }
202	
203	    if ((sq_map->reg_addr.addr != NULL) && (sq_map->reg_addr.addr != MAP_FAILED)) {
204	        (void)trs_dev_munmap(sq_map->reg_addr.addr, sq_map->reg_addr.len);
205	        sq_map->reg_addr.addr = NULL;
206	    }
207	}
