209	int trs_sq_mmap(uint32_t dev_id, struct halSqCqInputInfo *in, struct trs_sq_map *sq_map)
210	{
211	    long page_size = sysconf(_SC_PAGESIZE);
212	    int prot = (in->type == DRV_SHM_TYPE) ? PROT_READ : PROT_READ | PROT_WRITE;
213	    uint32_t que_mmap_len = 0;
214	    bool is_sq_mem_specified = ((in->flag & TSDRV_FLAG_SPECIFIED_SQ_MEM) != 0);
215	    int i;
216	
217	    if (!trs_is_mmap_sq(in)) {
218	        return 0;
219	    }
220	
221	    // mmap non reg addr, and set que
222	    que_mmap_len = (is_sq_mem_specified ? 0 : trs_get_sq_que_len(in->sqeDepth, in->sqeSize));
223	    sq_map->non_reg_addr.len = (size_t)(que_mmap_len + TRS_UIO_HEAD_REG * page_size);
224	    sq_map->non_reg_addr.addr = trs_dev_mmap(dev_id, NULL, sq_map->non_reg_addr.len, prot, MAP_SHARED);
225	    if (sq_map->non_reg_addr.addr == MAP_FAILED) {
226	        trs_err("Mmap non reg addr failed. (len=%lx)\n", sq_map->non_reg_addr.len);
227	        return DRV_ERROR_OUT_OF_MEMORY;
228	    }
229	
230	    if (!is_sq_mem_specified) {
231	        sq_map->que.addr = (void *)sq_map->non_reg_addr.addr;
232	        sq_map->que.len = trs_get_sq_que_len(in->sqeDepth, in->sqeSize);
233	    }
234	
235	    if (in->type == DRV_SHM_TYPE) { /* shm not need send */
236	        return 0;
237	    }
238	
239	    // mmap reg addr
240	    sq_map->reg_addr.len = (size_t)((TRS_UIO_ADDR_MAX - TRS_UIO_HEAD_REG) * page_size);
241	    sq_map->reg_addr.addr = trs_dev_mmap(dev_id, NULL, sq_map->reg_addr.len, PROT_READ, MAP_SHARED);
242	    if (sq_map->reg_addr.addr == MAP_FAILED) {
243	        trs_dev_munmap(sq_map->non_reg_addr.addr, sq_map->non_reg_addr.len);
244	        trs_err("Mmap addr failed. (len=%lx)\n", sq_map->reg_addr.len);
245	        return DRV_ERROR_OUT_OF_MEMORY;
246	    }
247	
248	    // set ctrl
249	    for (i = 0; i < TRS_UIO_ADDR_MAX; i++) {
250	        if (i < TRS_UIO_HEAD_REG) {
251	            sq_map->ctrl[i].addr = (void *)((uintptr_t)sq_map->non_reg_addr.addr + que_mmap_len +
252	                                            (size_t)(i * page_size));
253	        } else {
254	            sq_map->ctrl[i].addr = (void *)((uintptr_t)sq_map->reg_addr.addr +
255	                                            (size_t)((i - TRS_UIO_HEAD_REG) * page_size));
256	        }
257	    }
258	
259	    return 0;
260	}
