390	static int trs_sqcq_info_locks_init(struct sqcq_usr_info *info, uint32_t num)
391	{
392	    uint32_t i;
393	    int ret;
394	
395	    for (i = 0; i < num; i++) {
396	        ret = pthread_mutex_init(&info[i].sq_send_mutex, NULL);
397	        if (ret != 0) {
398	            goto destroy_inited_locks;
399	        }
400	
401	        ret = pthread_rwlock_init(&info[i].mutex, NULL);
402	        if (ret != 0) {
403	            (void)pthread_mutex_destroy(&info[i].sq_send_mutex);
404	            goto destroy_inited_locks;
405	        }
406	    }
407	
408	    return DRV_ERROR_NONE;
409	
410	destroy_inited_locks:
411	    while (i > 0) {
412	        i--;
413	        (void)pthread_rwlock_destroy(&info[i].mutex);
414	        (void)pthread_mutex_destroy(&info[i].sq_send_mutex);
415	    }
416	
417	    return ret;
418	}
419	
420	static void trs_sqcq_info_locks_destroy(struct sqcq_usr_info *info, uint32_t num)
421	{
422	    uint32_t i;
423	
424	    for (i = 0; i < num; i++) {
425	        (void)pthread_rwlock_destroy(&info[i].mutex);
426	        (void)pthread_mutex_destroy(&info[i].sq_send_mutex);
427	    }
428	}
429	
430	static int trs_id_type_init(uint32_t dev_id, uint32_t ts_id, int id_type, struct sqcq_usr_info **sqcq_info,
431	                            uint32_t *sqcq_num)
432	{
433	    struct trs_res_id_para para = {.tsid = ts_id, .res_type = id_type};
434	    struct sqcq_usr_info *info = NULL;
435	    uint32_t num;
436	    int ret;
437	
438	    if (id_type >= TRS_MAX_ID_TYPE) {
439	        *sqcq_info = NULL;
440	        *sqcq_num = 0;
441	        return 0;
442	    }
443	
444	    ret = trs_id_query(dev_id, TRS_RES_ID_MAX_QUERY, &para, &num);
445	    if (ret != DRV_ERROR_NONE) {
446	        trs_err("Query failed. (dev_id=%u; ts_id=%u; id_type=%d; ret=%d)\n", dev_id, ts_id, id_type, ret);
447	        return ret;
448	    }
449	
450	    if (num == 0) {
451	        *sqcq_info = NULL;
452	        *sqcq_num = 0;
453	        trs_info("No resource. (dev_id=%u; ts_id=%u; id_type=%d)\n", dev_id, ts_id, id_type);
454	        return DRV_ERROR_NONE;
455	    }
456	
457	    info = malloc(sizeof(*info) * num);
458	    if (info == NULL) {
459	        trs_err("Malloc failed. (dev_id=%u; ts_id=%u; id_type=%d; num=%u)\n", dev_id, ts_id, id_type, num);
460	        return DRV_ERROR_OUT_OF_MEMORY;
461	    }
462	
463	    ret = memset_s(info, sizeof(*info) * num, 0, sizeof(*info) * num);
464	    if (ret != 0) {
465	        free(info);
466	        trs_err("Memset failed. (dev_id=%u; ts_id=%u; id_type=%d; num=%u)\n", dev_id, ts_id, id_type, num);
467	        return ret;
468	    }
469	
470	    ret = trs_sqcq_info_locks_init(info, num);
471	    if (ret != DRV_ERROR_NONE) {
472	        free(info);
473	        trs_err("Mutex init failed. (dev_id=%u; ts_id=%u; id_type=%d; num=%u; ret=%d)\n", dev_id, ts_id, id_type, num,
474	                ret);
475	        return ret;
476	    }
477	
478	    *sqcq_info = info;
479	    *sqcq_num = num;
480	
481	    trs_info("Id type init success. (dev_id=%u; ts_id=%u; id_type=%d; num=%u)\n", dev_id, ts_id, id_type, num);
482	    return DRV_ERROR_NONE;
483	}
484	
485	static void trs_id_type_un_init(struct sqcq_usr_info **sqcq_info, uint32_t *sqcq_num)
486	{
487	    struct sqcq_usr_info *info = *sqcq_info;
488	
489	    if (info == NULL) {
490	        *sqcq_num = 0;
491	        return;
492	    }
493	
494	    trs_sqcq_info_locks_destroy(info, *sqcq_num);
495	
496	    free(info);
497	    *sqcq_info = NULL;
498	    *sqcq_num = 0;
499	}
500	
501	static int trs_ts_sq_cq_init(uint32_t dev_id, uint32_t ts_id)
502	{
503	    struct trs_sqcq_ctx *sqcq_ctx = NULL;
504	    drvSqCqType_t i, j;
505	    int ret;
506	
507	    for (i = 0; i < DRV_INVALID_TYPE; i++) {
508	        sqcq_ctx = trs_get_sqcq_ctx(dev_id, ts_id, i);
509	        ret = trs_id_type_init(dev_id, ts_id, trs_get_sq_id_type(i), &sqcq_ctx->sq_info, &sqcq_ctx->sq_num);
510	        if (ret != DRV_ERROR_NONE) {
511	            goto error;
512	        }
513	
514	        ret = trs_id_type_init(dev_id, ts_id, trs_get_cq_id_type(i), &sqcq_ctx->cq_info, &sqcq_ctx->cq_num);
515	        if (ret != DRV_ERROR_NONE) {
516	            trs_id_type_un_init(&sqcq_ctx->sq_info, &sqcq_ctx->sq_num);
517	            goto error;
518	        }
519	    }
520

