    if (trs_get_cq_id_type(in->type) >= TRS_MAX_ID_TYPE) {
        return;
    }

    if ((in->type == DRV_NORMAL_TYPE) && ((in->flag & TSDRV_FLAG_REUSE_CQ) != 0)) {
        return;
    }

    info = trs_get_cq_info(dev_id, in->tsId, in->type, in->cqId);
    if (info != NULL) {
